// Exercise get_numeric_type_size with supported enum values and assert sizes
{
    // Pick a supported numeric type deterministically from fuzzer input
    unsigned int r = *FUZZ_PARAM(unsigned int);
    faiss::NumericType nt;
    switch (r % 4) {
        case 0: nt = faiss::NumericType::Float32; break;
        case 1: nt = faiss::NumericType::Float16; break;
        case 2: nt = faiss::NumericType::UInt8; break;
        default: nt = faiss::NumericType::Int8; break;
    }
    size_t sz = faiss::get_numeric_type_size(nt);
    // Validate known sizes
    if (nt == faiss::NumericType::Float32) { FUZZ_ASSERT(sz == 4, "Float32 size must be 4"); }
    if (nt == faiss::NumericType::Float16) { FUZZ_ASSERT(sz == 2, "Float16 size must be 2"); }
    if (nt == faiss::NumericType::UInt8)   { FUZZ_ASSERT(sz == 1, "UInt8 size must be 1"); }
    if (nt == faiss::NumericType::Int8)    { FUZZ_ASSERT(sz == 1, "Int8 size must be 1"); }
}

